import java.nio.file.*;
import java.net.*;
import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import static org.objectweb.asm.Opcodes.*;

/** Actual commitNpc arithmetic prefix; status/config are explicit scalar edges, no server boot. */
public class BuildWorldPhysicalCommitOracle {
 static final String P="local/lito381/server/",S="com/lineage/server/",A=P+"SourceWorldPhysicalAttack",N=P+"SourceWorldPhysicalTarget",K=P+"SourceWorldPhysicalControl";
 static int checks,cases;
 static void need(boolean b,String why){checks++;if(!b)throw new AssertionError("source physical commit: "+why);}
 static void simple(ClassNode c,String name,String desc,int access,java.util.function.Consumer<MethodVisitor> body){BuildPoisonLeaseOracle.simple(c,name,desc,access,body);}
 static ClassNode type(String name){var c=new ClassNode();c.version=V17;c.access=ACC_PUBLIC;c.name=name;c.superName="java/lang/Object";simple(c,"<init>","()V",ACC_PUBLIC,m->{m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESPECIAL,"java/lang/Object","<init>","()V",false);m.visitInsn(RETURN);});return c;}
 static void write(Path output,ClassNode c)throws Exception{var writer=new ClassWriter(ClassWriter.COMPUTE_FRAMES|ClassWriter.COMPUTE_MAXS);c.accept(writer);var path=output.resolve(c.name+".class");Files.createDirectories(path.getParent());Files.write(path,writer.toByteArray());}
 public static void main(String[] args)throws Exception{
  var source=Path.of(args[0]);var output=Path.of(args[1]);var src=BuildPoisonLeaseOracle.read(source,S+"model/L1AttackPc");var method=src.methods.stream().filter(m->m.name.equals("commitNpc")&&m.desc.equals("()V")).findFirst().orElseThrow();
  var boundary=Arrays.stream(method.instructions.toArray()).filter(n->n instanceof MethodInsnNode m&&m.name.equals("calcAttackProcs")).findFirst().orElseThrow();var stop=boundary.getPrevious();need(stop instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==0,"prefix ends before actual proc calculation");
  var attack=type(A);for(String f:List.of("_isHit","_weaponType","_damage","_targetNpc"))attack.fields.add(new FieldNode(ACC_PUBLIC,f,f.equals("_isHit")?"Z":f.equals("_targetNpc")?"L"+N+";":"I",null,null));var prefix=new MethodNode(ACC_PUBLIC,"commitScalar","()I",null,null);var labels=new HashMap<LabelNode,LabelNode>();for(var n:method.instructions)if(n instanceof LabelNode l)labels.put(l,new LabelNode());
  for(var n=method.instructions.getFirst();n!=stop;n=n.getNext()){if(n instanceof FrameNode||n instanceof LineNumberNode)continue;var copied=n.clone(labels);if(copied instanceof FieldInsnNode f){if(f.owner.equals(S+"model/L1AttackPc")){need(List.of("_isHit","_weaponType","_damage","_targetNpc").contains(f.name),"only real scalar source fields");f.owner=A;if(f.name.equals("_targetNpc"))f.desc="L"+N+";";}else{need(f.getOpcode()==GETSTATIC&&f.owner.equals("com/lineage/config/ConfigSkill")&&f.name.equals("STRIKER_DMG2")&&f.desc.equals("D"),"one exact source control");f.owner=K;f.name="factor";}}if(copied instanceof MethodInsnNode m){need(m.name.equals("hasSkillEffect")&&m.desc.equals("(I)Z")&&m.owner.equals(S+"model/Instance/L1NpcInstance"),"only actual NPC status lookup");m.owner=N;}prefix.instructions.add(copied);}
  prefix.instructions.add(new VarInsnNode(ALOAD,0));prefix.instructions.add(new FieldInsnNode(GETFIELD,A,"_damage","I"));prefix.instructions.add(new InsnNode(IRETURN));attack.methods.add(prefix);write(output,attack);
  var ids=BuildPoisonLeaseOracle.read(source,S+"model/skill/L1SkillId");int striker=(int)ids.fields.stream().filter(f->f.name.equals("STRIKER_GALE")).findFirst().orElseThrow().value;
  var target=type(N);target.fields.add(new FieldNode(ACC_PUBLIC,"active","Z",null,null));simple(target,"hasSkillEffect","(I)Z",ACC_PUBLIC,m->{var no=new Label();m.visitVarInsn(ILOAD,1);m.visitLdcInsn(striker);m.visitJumpInsn(IF_ICMPNE,no);m.visitVarInsn(ALOAD,0);m.visitFieldInsn(GETFIELD,N,"active","Z");m.visitInsn(IRETURN);m.visitLabel(no);m.visitInsn(ICONST_0);m.visitInsn(IRETURN);});write(output,target);var config=type(K);config.fields.add(new FieldNode(ACC_PUBLIC|ACC_STATIC,"factor","D",null,null));write(output,config);
  var flow=BuildPoisonLeaseOracle.read(source,S+"model/combat/PcPhysicalAttackFlow");int flows=0;for(var m:flow.methods)if(Set.of("execute","executeAutoHunt").contains(m.name)){var calls=Arrays.stream(m.instructions.toArray()).filter(n->n instanceof MethodInsnNode x&&x.owner.equals(S+"model/L1AttackPc")).map(n->((MethodInsnNode)n).name).toList();need(calls.indexOf("action")>=0&&calls.indexOf("commitSideEffects")>calls.indexOf("action"),"actual action completes before commit flow="+m.name);flows++;}need(flows==2,"manual and automatic physical flow");
  var wrapper=src.methods.stream().filter(m->m.name.equals("commitSideEffects")).findFirst().orElseThrow();need(Arrays.stream(wrapper.instructions.toArray()).anyMatch(n->n instanceof MethodInsnNode m&&m.name.equals("commit")),"actual public side-effects wrapper delegates commit");
  var plan=BuildPoisonLeaseOracle.read(source,S+"model/combat/PhysicalHitCommitPlan");var after=plan.methods.stream().filter(m->m.name.equals("afterAccepted")).findFirst().orElseThrow();need(Arrays.stream(after.instructions.toArray()).anyMatch(n->n instanceof MethodInsnNode m&&m.owner.equals(S+"model/combat/DamageCommitOutcome")&&m.name.equals("accepted")),"actual physical effects gate on accepted HP outcome");
  need(Arrays.stream(method.instructions.toArray()).anyMatch(n->n instanceof MethodInsnNode m&&m.owner.equals(S+"model/combat/DamageEvent")&&m.name.equals("<init>"))&&Arrays.stream(method.instructions.toArray()).anyMatch(n->n instanceof MethodInsnNode m&&m.owner.equals(S+"model/combat/DamageCommit")&&m.name.equals("enqueue")),"actual physical uses direct DamageEvent enqueue, distinct from positive receiveDamage entry");
  try(var loader=new URLClassLoader(new URL[]{output.toUri().toURL()},ClassLoader.getPlatformClassLoader())){var ac=loader.loadClass(A.replace('/','.'));var nt=loader.loadClass(N.replace('/','.'));var ct=loader.loadClass(K.replace('/','.'));var call=ac.getMethod("commitScalar");for(int damage:new int[]{1,3,17,255,Integer.MAX_VALUE})for(int weapon:new int[]{0,4,20,62})for(boolean hit:new boolean[]{false,true})for(boolean active:new boolean[]{false,true})for(double factor:new double[]{-Double.MAX_VALUE,-2,-1,0,0.4,1.2,2,Double.MAX_VALUE}){var a=ac.getConstructor().newInstance();var t=nt.getConstructor().newInstance();nt.getField("active").set(t,active);ac.getField("_isHit").set(a,hit);ac.getField("_weaponType").set(a,weapon);ac.getField("_damage").set(a,damage);ac.getField("_targetNpc").set(a,t);ct.getField("factor").set(null,factor);int expected=hit&&active&&(weapon==20||weapon==62)?(int)(damage*factor):damage;need((int)call.invoke(a)==expected,"actual numeric prefix including signed/saturation and ranged guards");cases++;}}
  Files.writeString(Path.of(args[2]),"{\"source_actual_commitNpc_numeric_prefix_executed\":true,\"source_manual_and_auto_action_before_commit_compiled_order_verified\":true,\"source_direct_DamageEvent_enqueue_and_afterAccepted_gate_verified\":true,\"source_status_and_config_are_typed_scalar_edges\":true,\"source_full_PhysicalHitCommitPlan_effects_executed\":false,\"source_boot_SQL_or_scheduler_executed\":false,\"cases\":"+cases+",\"checks\":"+checks+"}\n");System.out.println("PASS actual PC-to-NPC physical commit prefix; cases="+cases+"; checks="+checks);
 }
}
